/// <summary>
/// Bug 216784: CB871-Business event not supplying correct details.
/// Moved the business event trigger in the confirm registration so it's called from both custom service and UI
/// </summary>
[ExtensionOf(classStr(InventTransWMS_Register))]
final class METInventTransWMS_Register_Extension
{
}

Method.Source:
/// <summary>
///    Converts the proposed changes into real inventory updates.
/// </summary>
/// <param name="_movementRecord">
///    The record that is used when it calls the registration form.
/// </param>
/// <returns>
///    true if the update succeeded; otherwise, false.
/// </returns>
public boolean updateInvent(Common _movementRecord)
{
    SalesLine salesLineReg;

    boolean result = next updateInvent(_movementRecord);

    if (result && _movementRecord is SalesLine)
    {
        SalesLine salesLine = _movementRecord as SalesLine;

        select firstonly RecId from salesLineReg
            where salesLineReg.SalesId == salesLine.SalesId    &&
                salesLineReg.ReturnStatus != ReturnStatusLine::Registered;

        if (!salesLineReg) // All lines are registered for the RMA
        {
            METSOReturnAndClaimsBusinessEvent::newFromSalesTable(salesLine.salesTable()).send();
        }
    }

    return result;
}
